function selectCampaigns(campaigns, maxSpend) {
  // Ensure we don't modify the original array
  const items = campaigns.map(c => ({
    id: c.id,
    spend: c.dailySpend,
    value: c.expectedSignups
  }));

  const max = Math.floor(maxSpend); // assume spend is integer‑compatible
  const dp = Array(max + 1).fill(null);
  dp[0] = { value: 0, spend: 0, ids: [] };

  const better = (a, b) => {
    if (!b) return true;
    if (a.value !== b.value) return a.value > b.value;
    if (a.spend !== b.spend) return a.spend < b.spend;
    const aKey = a.ids.slice().sort().join(',');
    const bKey = b.ids.slice().sort().join(',');
    return aKey < bKey;
  };

  for (const item of items) {
    const cost = Math.floor(item.spend);
    if (cost > max) continue; // cannot ever fit
    for (let w = max; w >= cost; w--) {
      const prev = dp[w - cost];
      if (!prev) continue;
      const candidate = {
        value: prev.value + item.value,
        spend: prev.spend + cost,
        ids: [...prev.ids, item.id]
      };
      if (better(candidate, dp[w])) {
        dp[w] = candidate;
      }
    }
  }

  // Find the overall best solution among all feasible spends
  let best = null;
  for (let w = 0; w <= max; w++) {
    if (dp[w] && better(dp[w], best)) {
      best = dp[w];
    }
  }

  return best ? best.ids.slice().sort() : [];
}
